css:
.pt-mesh {
  --c1: #0071e3;
  --c2: #8b5cf6;
  --c3: #14b8a6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-mesh {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-mesh>* {
  opacity: var(--o);
}

.pt-mesh i {
  position: absolute;
  width: calc(90% * var(--d));
  aspect-ratio: 1;
  border-radius: 50%;
  -webkit-mask: radial-gradient(closest-side,#000,transparent);
  mask: radial-gradient(closest-side,#000,transparent);
  will-change: transform;
  animation: pt-mesh-a calc(20s / var(--k)) ease-in-out infinite alternate;
}

.pt-mesh i:nth-child(1) {
  background: var(--c1);
  left: -12%;
  top: -15%;
}

.pt-mesh i:nth-child(2) {
  background: var(--c2);
  right: -12%;
  top: 5%;
  animation-name: pt-mesh-b;
}

.pt-mesh i:nth-child(3) {
  background: var(--c3);
  left: 15%;
  bottom: -25%;
  animation-name: pt-mesh-c;
  animation-duration: calc(24s / var(--k));
}

.pt-mesh i:nth-child(4) {
  background: color-mix(in srgb,var(--c1),var(--c2));
  right: 5%;
  bottom: -15%;
  animation-direction: alternate-reverse;
}

.pt-mesh i:nth-child(5) {
  background: color-mix(in srgb,var(--c3) 70%,#fff);
  left: 38%;
  top: 28%;
  width: calc(34% * var(--d));
  animation-name: pt-mesh-b;
  animation-duration: calc(16s / var(--k));
}

@keyframes pt-mesh-a {
  0% {
    transform: translate(0,0) scale(1);
  }
  50% {
    transform: translate(30%,20%) scale(1.2);
  }
  100% {
    transform: translate(-10%,40%) scale(.9);
  }
}

@keyframes pt-mesh-b {
  0% {
    transform: translate(0,0) scale(1);
  }
  50% {
    transform: translate(-35%,25%) scale(.85);
  }
  100% {
    transform: translate(-10%,-20%) scale(1.15);
  }
}

@keyframes pt-mesh-c {
  0% {
    transform: translate(0,0) scale(1.1);
  }
  50% {
    transform: translate(25%,-30%) scale(.9);
  }
  100% {
    transform: translate(45%,-5%) scale(1.2);
  }
}

