css:
.pt-aurora {
  --c1: #22d3a0;
  --c2: #8b5cf6;
  --c3: #0071e3;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-aurora {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-aurora>* {
  opacity: var(--o);
}

.pt-aurora b {
  position: absolute;
  left: -25%;
  width: 150%;
  height: 40%;
  top: 8%;
  border-radius: 50%;
  filter: blur(40px);
  mix-blend-mode: var(--blend,screen);
  will-change: transform;
  animation: pt-aurora-w calc(14s / var(--k)) ease-in-out infinite alternate;
}

.pt-aurora b:nth-child(1) {
  background: linear-gradient(90deg,transparent,var(--c1),color-mix(in srgb,var(--c1),var(--c3)),transparent);
  transform-origin: 30% 50%;
}

.pt-aurora b:nth-child(2) {
  top: 22%;
  height: 30%;
  background: linear-gradient(90deg,transparent 10%,var(--c2),transparent 85%);
  animation-duration: calc(18s / var(--k));
  animation-delay: -6s;
}

.pt-aurora b:nth-child(3) {
  top: 0;
  height: 25%;
  background: linear-gradient(90deg,transparent 20%,var(--c3),var(--c1),transparent);
  animation-duration: calc(11s / var(--k));
  animation-direction: alternate-reverse;
}

@keyframes pt-aurora-w {
  0% {
    transform: translateX(-8%) skewY(-6deg) scaleY(.8);
  }
  50% {
    transform: translateX(6%) skewY(4deg) scaleY(1.25);
  }
  100% {
    transform: translateX(-2%) skewY(-2deg) scaleY(.9);
  }
}

.pt-aurora i {
  position: absolute;
  width: calc(var(--z) * 1px * var(--d));
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--fg,#fff);
  animation: pt-aurora-t calc(3s / var(--k)) ease-in-out infinite;
  animation-delay: var(--t);
}

@keyframes pt-aurora-t {
  0%,100% {
    opacity: calc(var(--o) * .15);
  }
  50% {
    opacity: var(--o);
  }
}

