css:
.pt-breathe {
  --c1: #0071e3;
  --c2: #8b5cf6;
  --c3: #14b8a6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-breathe {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-breathe>* {
  opacity: var(--o);
}

.pt-breathe i {
  position: absolute;
  inset: -50%;
  background: conic-gradient(from 0deg,var(--c1),var(--c2),var(--c3),var(--c1));
  filter: blur(80px);
  will-change: transform;
  animation: pt-breathe-r calc(30s / var(--k)) linear infinite;
}

.pt-breathe b {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%,transparent 15%,var(--bg) 85%);
  animation: pt-breathe-b calc(8s / var(--k)) ease-in-out infinite;
}

@keyframes pt-breathe-r {
  to {
    transform: rotate(360deg);
  }
}

@keyframes pt-breathe-b {
  0%,100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.35);
  }
}

