css:
.pt-sunset {
  --c1: #f97316;
  --c2: #f43f5e;
  --c3: #8b5cf6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-sunset {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-sunset>* {
  opacity: var(--o);
}

.pt-sunset {
  background: linear-gradient(180deg,color-mix(in srgb,var(--c3) 45%,var(--bg)),color-mix(in srgb,var(--c2) 55%,var(--bg)) 50%,var(--c1))!important;
}

.pt-sunset::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 18%;
  width: 28%;
  aspect-ratio: 1;
  translate: -50% 0;
  border-radius: 50%;
  background: radial-gradient(circle,#fff8,var(--c1) 40%,transparent 70%);
  filter: blur(8px);
}

.pt-sunset i {
  position: absolute;
  left: 50%;
  width: 250%;
  aspect-ratio: 1;
  margin-left: -125%;
  border-radius: 43%;
  will-change: transform;
  animation: pt-sunset-r calc(22s / var(--k)) linear infinite;
}

.pt-sunset i:nth-child(1) {
  top: 44%;
  background: color-mix(in srgb,var(--c1) 70%,transparent);
}

.pt-sunset i:nth-child(2) {
  top: 54%;
  border-radius: 40%;
  background: color-mix(in srgb,var(--c2) 75%,var(--bg));
  animation-duration: calc(16s / var(--k));
  animation-direction: reverse;
}

.pt-sunset i:nth-child(3) {
  top: 65%;
  border-radius: 45%;
  background: color-mix(in srgb,var(--c3) 60%,var(--bg));
  animation-duration: calc(12s / var(--k));
}

.pt-sunset i:nth-child(4) {
  top: 78%;
  border-radius: 42%;
  background: var(--bg);
  animation-duration: calc(26s / var(--k));
  animation-direction: reverse;
}

@keyframes pt-sunset-r {
  to {
    transform: rotate(360deg);
  }
}

