.pt-dots {
  --c1: #0071e3;
  --c2: #8b5cf6;
  --c3: #14b8a6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-dots {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-dots>* {
  opacity: var(--o);
}

.pt-dots {
  display: grid;
  grid-template-columns: repeat(22,1fr);
  grid-template-rows: repeat(14,1fr);
  place-items: center;
  padding: 2%;
}

.pt-dots i {
  width: calc(6px * var(--d));
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--c1);
  animation: pt-dots-w calc(3.2s / var(--k)) ease-in-out infinite backwards;
  animation-delay: calc(var(--r) * .12s / var(--k));
}

@keyframes pt-dots-w {
  0%,100% {
    transform: scale(.6);
    opacity: calc(var(--o) * .25);
  }
  18% {
    transform: scale(1.8);
    opacity: var(--o);
    background: var(--c2);
    box-shadow: 0 0 14px var(--c2);
  }
  40% {
    transform: scale(1);
    opacity: calc(var(--o) * .6);
    background: var(--c3);
  }
}

