css:
.pt-synth {
  --c1: #8b5cf6;
  --c2: #0071e3;
  --c3: #f472b6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-synth {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-synth>* {
  opacity: var(--o);
}

.pt-synth {
  background: linear-gradient(180deg,var(--bg) 0%,color-mix(in srgb,var(--c1) 40%,var(--bg)) 50%,var(--bg) 50%)!important;
}

.pt-synth b {
  position: absolute;
  left: 50%;
  bottom: 50%;
  width: 34%;
  max-width: 420px;
  aspect-ratio: 1;
  translate: -50% 28%;
  border-radius: 50%;
  background: linear-gradient(180deg,var(--c3),var(--c1));
  -webkit-mask: linear-gradient(#000 52%,transparent 52% 57%,#000 57% 66%,transparent 66% 70%,#000 70% 77%,transparent 77% 82%,#000 82% 87%,transparent 87% 92%,#000 92%);
  mask: linear-gradient(#000 52%,transparent 52% 57%,#000 57% 66%,transparent 66% 70%,#000 70% 77%,transparent 77% 82%,#000 82% 87%,transparent 87% 92%,#000 92%);
}

.pt-synth i {
  position: absolute;
  left: -50%;
  width: 200%;
  top: 50%;
  height: 120%;
  transform-origin: 50% 0;
  transform: perspective(600px) rotateX(70deg);
  background-image: linear-gradient(var(--c2) 2px,transparent 2px),linear-gradient(90deg,var(--c2) 2px,transparent 2px);
  background-size: calc(60px * var(--d)) calc(60px * var(--d));
  -webkit-mask: linear-gradient(180deg,transparent,#000 35%);
  mask: linear-gradient(180deg,transparent,#000 35%);
  animation: pt-synth-m calc(1.2s / var(--k)) linear infinite;
}

.pt-synth u {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  background: var(--c3);
  box-shadow: 0 0 30px 6px var(--c3);
}

@keyframes pt-synth-m {
  to {
    background-position: 0 calc(60px * var(--d));
  }
}

