css:
.pt-hex {
  --c1: #0071e3;
  --c2: #8b5cf6;
  --c3: #14b8a6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-hex {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-hex>* {
  opacity: var(--o);
}

.pt-hex {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  --w: calc(56px * var(--d));
}

.pt-hex p {
  display: flex;
  gap: 4px;
  margin: 0 0 calc(var(--w) * -0.2887 + 4px);
  flex-shrink: 0;
}

.pt-hex p:nth-child(even) {
  transform: translateX(calc(var(--w) / 2 + 2px));
}

.pt-hex i {
  flex-shrink: 0;
  width: var(--w);
  height: calc(var(--w) * 1.1547);
  clip-path: polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);
  background: color-mix(in srgb,var(--c1) 10%,var(--bg));
  animation: pt-hex-g calc(var(--t) / var(--k)) ease-in-out infinite;
  animation-delay: calc(var(--dl) * -1s);
}

.pt-hex p:nth-child(3n) i:nth-child(odd) {
  animation-name: pt-hex-g2;
}

.pt-hex::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle,transparent 30%,var(--bg) 95%);
  pointer-events: none;
}

@keyframes pt-hex-g {
  0%,70%,100% {
    background: color-mix(in srgb,var(--c1) 10%,var(--bg));
  }
  82% {
    background: color-mix(in srgb,var(--c1) 85%,var(--c2));
  }
}

@keyframes pt-hex-g2 {
  0%,70%,100% {
    background: color-mix(in srgb,var(--c1) 10%,var(--bg));
  }
  82% {
    background: color-mix(in srgb,var(--c3) 85%,var(--c2));
  }
}

