css:
.pt-diag {
  --c1: #0071e3;
  --c2: #8b5cf6;
  --c3: #14b8a6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-diag {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-diag>* {
  opacity: var(--o);
}

.pt-diag {
  --p: calc(15px * var(--d));
}

.pt-diag i,.pt-diag b {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(135deg,transparent 0 calc(var(--p) - 1px),var(--lc) calc(var(--p) - 1px) var(--p));
  animation: pt-diag-m calc(4s / var(--k)) linear infinite;
}

.pt-diag i {
  --lc: color-mix(in srgb,var(--c1) 28%,transparent);
}

.pt-diag b {
  --lc: var(--c2);
  filter: drop-shadow(0 0 6px var(--c2));
  -webkit-mask: linear-gradient(135deg,transparent 40%,#000 50%,transparent 60%) 0 0/300% 300%;
  mask: linear-gradient(135deg,transparent 40%,#000 50%,transparent 60%) 0 0/300% 300%;
  animation: pt-diag-m calc(4s / var(--k)) linear infinite,pt-diag-s calc(6s / var(--k)) ease-in-out infinite;
}

.pt-diag b:nth-child(3) {
  --lc: var(--c3);
  animation-delay: 0s,calc(-3s / var(--k));
}

@keyframes pt-diag-m {
  to {
    background-position: calc(var(--p) * 1.41421) 0;
  }
}

@keyframes pt-diag-s {
  from {
    -webkit-mask-position: 100% 100%;
    mask-position: 100% 100%;
  }
  to {
    -webkit-mask-position: 0 0;
    mask-position: 0 0;
  }
}

