  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-snow {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-snow>* {
  opacity: var(--o);
}

.pt-snow {
  background: radial-gradient(ellipse at 50% 0%,color-mix(in srgb,var(--c1) 35%,var(--bg)),var(--bg) 70%)!important;
}

.pt-snow i {
  position: absolute;
  inset: -10%;
  background-image: radial-gradient(circle at 15% 20%,color-mix(in srgb,var(--c3) 55%,var(--fg)) var(--r),transparent calc(var(--r) + 1px)),radial-gradient(circle at 65% 55%,color-mix(in srgb,var(--c3) 55%,var(--fg)) var(--r),transparent calc(var(--r) + 1px)),radial-gradient(circle at 40% 85%,color-mix(in srgb,var(--c3) 55%,var(--fg)) var(--r),transparent calc(var(--r) + 1px)),radial-gradient(circle at 85% 10%,color-mix(in srgb,var(--c2) 70%,var(--fg)) var(--r),transparent calc(var(--r) + 1px));
  background-size: var(--sz) var(--sz);
  animation: pt-snow-f calc(var(--t) / var(--k)) linear infinite,pt-snow-s calc(var(--t) * .6 / var(--k)) ease-in-out infinite alternate;
}

