css:
.pt-fireflies {
  --c1: #d9f99d;
  --c2: #fde68a;
  --c3: #14532d;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-fireflies {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-fireflies>* {
  opacity: var(--o);
}

.pt-fireflies {
  background: linear-gradient(0deg,color-mix(in srgb,var(--c3) 70%,var(--bg)),var(--bg) 75%)!important;
}

.pt-fireflies b {
  position: absolute;
  inset: auto -10% -20% -10%;
  height: 60%;
  background: radial-gradient(ellipse at 50% 100%,color-mix(in srgb,var(--c3) 80%,transparent),transparent 70%);
  filter: blur(30px);
}

.pt-fireflies i {
  position: absolute;
  width: calc(var(--z) * 1px * var(--d));
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle,#fff,var(--c1) 45%,transparent 72%);
  box-shadow: 0 0 14px 4px color-mix(in srgb,var(--c1) 55%,transparent);
  animation: pt-ff-m calc(var(--t) / var(--k)) ease-in-out infinite alternate,pt-ff-b calc(var(--t) / 2.5 / var(--k)) ease-in-out infinite;
  animation-delay: var(--dl);
}

.pt-fireflies i:nth-child(3n) {
  background: radial-gradient(circle,#fff,var(--c2) 45%,transparent 72%);
  box-shadow: 0 0 14px 4px color-mix(in srgb,var(--c2) 55%,transparent);
  animation-name: pt-ff-m2,pt-ff-b;
}

.pt-fireflies i:nth-child(3n+1) {
  animation-name: pt-ff-m3,pt-ff-b;
}

@keyframes pt-ff-m {
  0% {
    transform: translate(0,0);
  }
  33% {
    transform: translate(30px,-40px);
  }
  66% {
    transform: translate(-20px,-70px);
  }
  100% {
    transform: translate(15px,-20px);
  }
}

@keyframes pt-ff-m2 {
  0% {
    transform: translate(0,0);
  }
  50% {
    transform: translate(-40px,-30px);
  }
  100% {
    transform: translate(20px,-60px);
  }
}

@keyframes pt-ff-m3 {
  0% {
    transform: translate(0,0);
  }
  40% {
    transform: translate(25px,30px);
  }
  100% {
    transform: translate(-30px,-15px);
  }
}

@keyframes pt-ff-b {
  0%,100% {
    opacity: calc(var(--o) * .1);
  }
  50% {
    opacity: var(--o);
  }
}

