css:
.pt-grain {
  --c1: #0071e3;
  --c2: #8b5cf6;
  --c3: #14b8a6;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-grain {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-grain>* {
  opacity: var(--o);
}

.pt-grain {
  background: radial-gradient(120% 90% at 15% 10%,color-mix(in srgb,var(--c1) 55%,var(--bg)),transparent 60%),radial-gradient(100% 80% at 90% 95%,color-mix(in srgb,var(--c2) 50%,var(--bg)),transparent 60%),var(--bg)!important;
}

.pt-grain b {
  position: absolute;
  inset: 0;
  background: radial-gradient(40% 50% at 70% 30%,color-mix(in srgb,var(--c3) 45%,transparent),transparent);
  animation: pt-grain-d calc(12s / var(--k)) ease-in-out infinite alternate;
}

.pt-grain i {
  position: absolute;
  inset: -100%;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  background-size: calc(200px * var(--d));
  opacity: calc(var(--o) * .22);
  mix-blend-mode: overlay;
  animation: pt-grain-j calc(0.8s / var(--k)) steps(1) infinite;
}

@keyframes pt-grain-d {
  from {
    transform: translate(-10%,5%) scale(1);
  }
  to {
    transform: translate(10%,-5%) scale(1.3);
  }
}

@keyframes pt-grain-j {
  0% {
    transform: translate(0,0);
  }
  20% {
    transform: translate(-5%,-10%);
  }
  40% {
    transform: translate(-15%,5%);
  }
  60% {
    transform: translate(7%,-25%);
  }
  80% {
    transform: translate(-5%,25%);
  }
  100% {
    transform: translate(0,0);
  }
}

