(function (el) {
const cv=el.querySelector("canvas"),x=cv.getContext("2d");let W=0,H=0,raf=0;
const fit=()=>{const r=Math.min(window.devicePixelRatio||1,2);W=el.clientWidth;H=el.clientHeight;cv.width=W*r;cv.height=H*r;x.setTransform(r,0,0,r,0,0)};
const ro=new ResizeObserver(fit);ro.observe(el);fit();
const V=()=>{const s=getComputedStyle(el),g=(n)=>s.getPropertyValue(n).trim();return{c1:g("--c1"),c2:g("--c2"),c3:g("--c3"),bg:g("--bg"),k:+g("--k")||1,d:+g("--d")||1}};
// Movimiento reducido: se calculan de golpe unos fotogramas (con tiempo simulado) y la escena se queda quieta
const RM=matchMedia("(prefers-reduced-motion: reduce)").matches;let RF=0;
const requestAnimationFrame=(f)=>{if(!RM)return window.requestAnimationFrame(f);if(++RF<400)f(RF*60);return 0};
const CH="アイウエオカキクケコサシスセソタチツテト0123456789ABCDEF<>/*+=";let cols=[],last=0,acc=0;
const loop=(t)=>{raf=requestAnimationFrame(loop);const v=V();acc+=(t-last)*v.k;last=t;if(acc<55)return;acc=0;
const fs=Math.max(8,Math.min(40,Math.round(18/v.d))),n=Math.ceil(W/fs);if(cols.length!==n)cols=Array.from({length:n},()=>Math.random()*-60);
x.globalAlpha=.1;x.fillStyle=v.bg;x.fillRect(0,0,W,H);x.globalAlpha=1;x.font=fs+"px ui-monospace,monospace";
for(let i=0;i<n;i++){const y=cols[i]*fs;x.fillStyle=v.c1;x.fillText(CH[Math.floor(Math.random()*CH.length)],i*fs,y-fs);x.fillStyle=v.c2;x.shadowColor=v.c1;x.shadowBlur=8;x.fillText(CH[Math.floor(Math.random()*CH.length)],i*fs,y);x.shadowBlur=0;
if(y>H&&Math.random()>.975)cols[i]=0;cols[i]++}};raf=requestAnimationFrame(loop);
