css:
.pt-iso-cubes {
  --c1: #e0e7ff;
  --c2: #818cf8;
  --c3: #312e81;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-iso-cubes {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-iso-cubes>* {
  opacity: var(--o);
}

.pt-iso-cubes svg {
  position: absolute;
  inset: -100%;
  width: 300%;
  height: 300%;
  scale: var(--d);
  animation: pt-iso calc(16s / var(--k)) linear infinite;
}

.pt-iso-cubes .t {
  fill: var(--c1);
}

.pt-iso-cubes .l {
  fill: var(--c2);
}

.pt-iso-cubes .r {
  fill: var(--c3);
}

.pt-iso-cubes .lt {
  position: absolute;
  inset: 0;
  background: radial-gradient(40% 55% at 50% 50%,rgba(255,255,255,.45),transparent 70%);
  background-size: 200% 200%;
  mix-blend-mode: soft-light;
  animation: pt-iso-l calc(9s / var(--k)) ease-in-out infinite alternate;
}

@keyframes pt-iso {
  to {
    translate: 38.105px 66px;
  }
}

@keyframes pt-iso-l {
  from {
    background-position: 0% 0%;
  }
  to {
    background-position: 100% 100%;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-iso-cubes svg,.pt-iso-cubes .lt {
    animation: none;
  }
}

