css:
.pt-bokeh {
  --c1: #fbbf24;
  --c2: #f472b6;
  --c3: #60a5fa;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-bokeh {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-bokeh>* {
  opacity: var(--o);
}

.pt-bokeh {
  background-image: radial-gradient(120% 80% at 50% 110%,color-mix(in srgb,var(--c2) 18%,transparent),transparent 70%);
}

.pt-bokeh i {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: calc(var(--s) * var(--d));
  aspect-ratio: 1;
  margin: calc(var(--s) * var(--d) / -2) 0 0 calc(var(--s) * var(--d) / -2);
  border-radius: 50%;
  background: radial-gradient(circle,color-mix(in srgb,var(--c) 30%,transparent) 0 52%,color-mix(in srgb,var(--c) 60%,transparent) 64%,transparent 70%);
  filter: blur(var(--b));
  mix-blend-mode: var(--blend);
  animation: pt-bokeh calc(var(--du) * 1s / var(--k)) ease-in-out infinite alternate;
  animation-delay: calc(var(--dl) * 1s / var(--k));
}

@keyframes pt-bokeh {
  0% {
    transform: none;
    opacity: .35;
  }
  50% {
    opacity: 1;
  }
  100% {
    transform: translate(var(--tx),var(--ty)) scale(1.25);
    opacity: .55;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-bokeh i {
    animation: none;
    opacity: .7;
  }
}

