css:
.pt-uvq16-blueprint {
  --c1: #1d4f91;
  --c2: #eaf2ff;
  --c3: #ffb020;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-blueprint {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-blueprint>* {
  opacity: var(--o);
}

.pt-uvq16-blueprint {
  background: radial-gradient(130% 100% at 50% 35%,color-mix(in srgb,var(--c1) 90%,#fff),color-mix(in srgb,var(--c1) 70%,#000));
}

.pt-uvq16-blueprint .g {
  position: absolute;
  inset: 0;
  --a: calc(64px / var(--d));
  --b: calc(var(--a) / 5);
  background-image: linear-gradient(color-mix(in srgb,var(--c2) 24%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--c2) 24%,transparent) 1px,transparent 1px),linear-gradient(color-mix(in srgb,var(--c2) 9%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--c2) 9%,transparent) 1px,transparent 1px);
  background-size: var(--a) var(--a),var(--a) var(--a),var(--b) var(--b),var(--b) var(--b);
  background-position: center;
}

.pt-uvq16-blueprint svg {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(84cqw,125cqh);
  translate: -50% -50%;
  overflow: visible;
  fill: none;
  stroke: var(--c2);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.pt-uvq16-blueprint .w {
  stroke-width: 4;
}

.pt-uvq16-blueprint .t {
  stroke-width: 1.5;
}

.pt-uvq16-blueprint .d {
  stroke-width: 1;
  stroke: var(--c3);
}

.pt-uvq16-blueprint path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: uvq16-bp-draw calc(14s / var(--k)) cubic-bezier(.45,0,.2,1) infinite;
  animation-delay: calc(var(--i) * .45s / var(--k));
}

.pt-uvq16-blueprint text {
  fill: var(--c3);
  stroke: none;
  font: 600 9px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  letter-spacing: .12em;
  text-anchor: middle;
  opacity: 0;
  animation: uvq16-bp-fade calc(14s / var(--k)) ease infinite;
}

.pt-uvq16-blueprint .cx,.pt-uvq16-blueprint .cy {
  position: absolute;
  left: 0;
  top: 0;
  pointer-events: none;
}

.pt-uvq16-blueprint .cx {
  width: 1px;
  height: 100%;
  background: repeating-linear-gradient(var(--c3) 0 6px,transparent 6px 10px);
  translate: var(--px,30cqw) 0;
  animation: uvq16-bp-x calc(11s / var(--k)) ease-in-out infinite alternate;
}

.pt-uvq16-blueprint .cy {
  height: 1px;
  width: 100%;
  background: repeating-linear-gradient(90deg,var(--c3) 0 6px,transparent 6px 10px);
  translate: 0 var(--py,40cqh);
  animation: uvq16-bp-y calc(7s / var(--k)) ease-in-out infinite alternate;
}

.pt-uvq16-blueprint[data-on] .cx,.pt-uvq16-blueprint[data-on] .cy {
  animation: none;
}

.pt-uvq16-blueprint .rd {
  position: absolute;
  left: 14px;
  top: 14px;
  font: 600 11px/1 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  letter-spacing: .08em;
  color: var(--c2);
  padding: 6px 9px;
  border: 1px solid color-mix(in srgb,var(--c2) 45%,transparent);
  background: color-mix(in srgb,var(--c1) 80%,transparent);
  font-variant-numeric: tabular-nums;
}

@keyframes uvq16-bp-draw {
  0% {
    stroke-dashoffset: 1;
    opacity: 1;
  }
  30% {
    stroke-dashoffset: 0;
  }
  86% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
  96%,100% {
    stroke-dashoffset: 0;
    opacity: 0;
  }
}

@keyframes uvq16-bp-fade {
  0%,40% {
    opacity: 0;
  }
  50%,86% {
    opacity: 1;
  }
  96%,100% {
    opacity: 0;
  }
}

@keyframes uvq16-bp-x {
  from {
    translate: 18cqw 0;
  }
  to {
    translate: 82cqw 0;
  }
}

@keyframes uvq16-bp-y {
  from {
    translate: 0 22cqh;
  }
  to {
    translate: 0 78cqh;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-blueprint path {
    animation: none;
    stroke-dashoffset: 0;
  }
  .pt-uvq16-blueprint text {
    animation: none;
    opacity: 1;
  }
  .pt-uvq16-blueprint .cx,.pt-uvq16-blueprint .cy {
    animation: none;
  }
}

