.pt-uvq16-terrazzo {
  --c1: #d0643c;
  --c2: #8fa98b;
  --c3: #e0a83a;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-terrazzo {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-terrazzo>* {
  opacity: var(--o);
}

.pt-uvq16-terrazzo {
  background-color: color-mix(in srgb,var(--fg) 6%,var(--bg));
}

.pt-uvq16-terrazzo::before {
  content: "";
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  opacity: .14;
  mix-blend-mode: var(--blend);
}

.pt-uvq16-terrazzo .tl {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% * var(--d));
  height: calc(100% * var(--d));
  transform-origin: 0 0;
  scale: calc(1 / var(--d));
}

.pt-uvq16-terrazzo .a {
  fill: var(--c1);
}

.pt-uvq16-terrazzo .b {
  fill: var(--c2);
}

.pt-uvq16-terrazzo .c {
  fill: var(--c3);
}

.pt-uvq16-terrazzo .e {
  fill: color-mix(in srgb,var(--fg) 72%,var(--bg));
}

.pt-uvq16-terrazzo .f {
  fill: color-mix(in srgb,var(--bg) 40%,#fff);
}

.pt-uvq16-terrazzo .mi i {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 6px 1px rgba(255,255,255,.85),0 0 0 .5px rgba(0,0,0,.15);
  opacity: 0;
  animation: uvq16-tz-tw calc(5s / var(--k)) ease-in-out infinite;
  animation-delay: var(--dl);
}

.pt-uvq16-terrazzo .lt {
  position: absolute;
  inset: 0;
  background: radial-gradient(45% 55% at calc(50% + var(--mx,0) * 100%) calc(40% + var(--my,0) * 100%),rgba(255,255,255,.5),transparent 70%);
  mix-blend-mode: soft-light;
  transition: background .3s;
}

.pt-uvq16-terrazzo .sh {
  position: absolute;
  inset: -50%;
  background: linear-gradient(115deg,transparent 42%,rgba(255,255,255,.4) 50%,transparent 58%);
  mix-blend-mode: soft-light;
  animation: uvq16-tz-sh calc(10s / var(--k)) ease-in-out infinite;
}

@keyframes uvq16-tz-tw {
  0%,70%,100% {
    opacity: 0;
    scale: .3;
  }
  82% {
    opacity: 1;
    scale: 1;
  }
}

@keyframes uvq16-tz-sh {
  from {
    translate: -30% -10%;
  }
  to {
    translate: 30% 10%;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-terrazzo .mi i,.pt-uvq16-terrazzo .sh {
    animation: none;
  }
  .pt-uvq16-terrazzo .mi i {
    opacity: .6;
  }
}

