css:
.pt-uvq16-paper-tunnel {
  --c1: #f4e1c1;
  --c2: #c8553d;
  --c3: #ffd27a;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-paper-tunnel {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-paper-tunnel>* {
  opacity: var(--o);
}

.pt-uvq16-paper-tunnel {
  background: radial-gradient(circle at calc(50% + var(--mx,0) * -20%) calc(50% + var(--my,0) * -20%),var(--c3),color-mix(in srgb,var(--c2) 70%,#000) 40%);
}

.pt-uvq16-paper-tunnel .st {
  position: absolute;
  inset: 0;
  scale: calc(.8 + var(--d) * .2);
}

.pt-uvq16-paper-tunnel .ly {
  position: absolute;
  left: -14%;
  top: -14%;
  width: 128%;
  height: 128%;
  fill: color-mix(in srgb,color-mix(in srgb,var(--c1) calc(var(--i) * 12.5%),var(--c2)),var(--bg) 8%);
  filter: drop-shadow(0 calc(3px + var(--i) * .5px) calc(6px + var(--i) * .6px) rgba(0,0,0,.42));
  translate: calc(var(--mx,0) * var(--i) * -9px) calc(var(--my,0) * var(--i) * -9px);
  transition: translate .9s cubic-bezier(.22,1,.36,1);
  animation: uvq16-pp-sw calc((16s + var(--i) * 2.5s) / var(--k)) ease-in-out infinite alternate;
  will-change: transform;
}

.pt-uvq16-paper-tunnel .nz {
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  opacity: .16;
  mix-blend-mode: multiply;
  pointer-events: none;
}

@keyframes uvq16-pp-sw {
  from {
    rotate: calc(var(--r) * -3deg);
    scale: 1;
  }
  to {
    rotate: calc(var(--r) * 3deg);
    scale: 1.03;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-paper-tunnel .ly {
    animation: none;
    transition: none;
  }
}

