css:
.pt-uvq16-thermal {
  --c1: #4c1d95;
  --c2: #f0541e;
  --c3: #fde68a;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-thermal {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-thermal>* {
  opacity: var(--o);
}

.pt-uvq16-thermal canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.pt-uvq16-thermal {
  background: #06030f;
  font: 600 11px/1 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  color: #fff;
}

.pt-uvq16-thermal .hud {
  position: absolute;
  inset: 14px;
  pointer-events: none;
  --l: linear-gradient(#fff,#fff);
  background: var(--l) top left/18px 2px,var(--l) top left/2px 18px,var(--l) top right/18px 2px,var(--l) top right/2px 18px,var(--l) bottom left/18px 2px,var(--l) bottom left/2px 18px,var(--l) bottom right/18px 2px,var(--l) bottom right/2px 18px;
  background-repeat: no-repeat;
  opacity: .85;
}

.pt-uvq16-thermal .sc {
  position: absolute;
  right: 26px;
  top: 50%;
  width: 8px;
  height: 44%;
  translate: 0 -50%;
  border: 1px solid rgba(255,255,255,.7);
  background: linear-gradient(to top,#06030f,var(--c1) 30%,var(--c2) 60%,var(--c3) 85%,#fff);
}

.pt-uvq16-thermal .sc b {
  position: absolute;
  right: 14px;
  font-weight: 600;
  text-shadow: 0 1px 2px #000;
}

.pt-uvq16-thermal .sc b:first-child {
  top: -4px;
}

.pt-uvq16-thermal .sc b:last-child {
  bottom: -4px;
}

.pt-uvq16-thermal .mk {
  position: absolute;
  left: 0;
  top: 0;
  width: 24px;
  height: 24px;
  margin: -12px 0 0 -12px;
  border: 1.5px solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(0,0,0,.4);
  transition: translate .25s ease-out;
  pointer-events: none;
}

.pt-uvq16-thermal .mk::before,.pt-uvq16-thermal .mk::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  background: #fff;
  translate: -50% -50%;
}

.pt-uvq16-thermal .mk::before {
  width: 36px;
  height: 1.5px;
}

.pt-uvq16-thermal .mk::after {
  width: 1.5px;
  height: 36px;
}

.pt-uvq16-thermal .rd {
  position: absolute;
  left: 30px;
  top: -14px;
  white-space: nowrap;
  padding: 3px 5px;
  background: rgba(0,0,0,.55);
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-thermal .mk {
    transition: none;
  }
}

