css:
.pt-uvq16-oscilloscope {
  --c1: #39ff88;
  --c2: #eaffd0;
  --c3: #7c8a84;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-oscilloscope {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-oscilloscope>* {
  opacity: var(--o);
}

.pt-uvq16-oscilloscope canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.pt-uvq16-oscilloscope {
  background: #040e09;
}

.pt-uvq16-oscilloscope .gr {
  position: absolute;
  inset: 6%;
  border: 1px solid color-mix(in srgb,var(--c3) 60%,transparent);
  border-radius: 6px;
  background-image: linear-gradient(color-mix(in srgb,var(--c3) 30%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--c3) 30%,transparent) 1px,transparent 1px);
  background-size: 10% 12.5%;
  background-position: -.5px -.5px;
  pointer-events: none;
}

.pt-uvq16-oscilloscope .gr::before,.pt-uvq16-oscilloscope .gr::after {
  content: "";
  position: absolute;
}

.pt-uvq16-oscilloscope .gr::before {
  left: 0;
  right: 0;
  top: 50%;
  height: 9px;
  translate: 0 -50%;
  background: repeating-linear-gradient(90deg,color-mix(in srgb,var(--c3) 70%,transparent) 0 1px,transparent 1px 2%);
}

.pt-uvq16-oscilloscope .gr::after {
  top: 0;
  bottom: 0;
  left: 50%;
  width: 9px;
  translate: -50% 0;
  background: repeating-linear-gradient(color-mix(in srgb,var(--c3) 70%,transparent) 0 1px,transparent 1px 2.5%);
}

.pt-uvq16-oscilloscope .gl {
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 95% at 50% 50%,transparent 58%,rgba(0,0,0,.6)),linear-gradient(155deg,rgba(255,255,255,.08),transparent 38%);
  pointer-events: none;
}

