css:
.pt-uvq16-memphis {
  --c1: #ffc845;
  --c2: #16b3a0;
  --c3: #ff5c8a;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-memphis {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-memphis>* {
  opacity: var(--o);
}

.pt-uvq16-memphis {
  font-size: 14px;
  background-image: radial-gradient(color-mix(in srgb,var(--fg) 16%,transparent) 1.2px,transparent 1.7px);
  background-size: calc(22px * var(--d)) calc(22px * var(--d));
}

.pt-uvq16-memphis svg {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: calc(var(--w) * 1em * var(--d));
  overflow: visible;
  rotate: var(--r);
  translate: calc(-50% + var(--px,0px)) calc(-50% + var(--py,0px));
  transition: translate .6s cubic-bezier(.34,1.56,.64,1);
  animation: uvq16-mp-f calc(var(--t) * 1s / var(--k)) ease-in-out infinite alternate;
  animation-delay: calc(var(--dl) * 1s / var(--k));
}

.pt-uvq16-memphis .a {
  color: var(--c1);
}

.pt-uvq16-memphis .b {
  color: var(--c2);
}

.pt-uvq16-memphis .c {
  color: var(--c3);
}

.pt-uvq16-memphis .f {
  color: var(--fg);
}

.pt-uvq16-memphis .k {
  fill: none;
  stroke: var(--fg);
  stroke-width: 2.5;
  stroke-linejoin: round;
}

.pt-uvq16-memphis .kd {
  fill: var(--fg);
}

@keyframes uvq16-mp-f {
  from {
    transform: translate(0,0) rotate(-7deg);
  }
  to {
    transform: translate(var(--dx),var(--dy)) rotate(9deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-memphis svg {
    animation: none;
    transition: none;
  }
}

