.pt-uvq16-seigaiha {
  --c1: #1f3a6e;
  --c2: #f3ecdc;
  --c3: #d4a636;
  --k: 1;
  /* velocidad */
  --d: 1;
  /* densidad / escala */
  --o: 1;
  /* opacidad */
  --bg: #05060a;
  --fg: #ffffff;
  --blend: screen;
  min-height: 100vh;
}

.pt-uvq16-seigaiha {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg);
  container-type: size;
  isolation: isolate;
}

.pt-uvq16-seigaiha>* {
  opacity: var(--o);
}

@property --uvq16-gx {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 50%;
}

@property --uvq16-gy {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 50%;
}

.pt-uvq16-seigaiha {
  background: var(--c1);
}

.pt-uvq16-seigaiha .tl {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% * var(--d) + 80px);
  height: calc(100% * var(--d));
  transform-origin: 0 0;
  scale: calc(1 / var(--d));
  animation: uvq16-sg-dr calc(24s / var(--k)) linear infinite;
}

.pt-uvq16-seigaiha .f {
  fill: var(--c1);
  stroke: var(--c2);
  stroke-width: 2.6;
}

.pt-uvq16-seigaiha .w {
  fill: none;
  stroke: var(--c2);
  stroke-width: 2.6;
}

.pt-uvq16-seigaiha .w0 {
  fill: var(--c2);
}

.pt-uvq16-seigaiha .gd {
  position: absolute;
  inset: 0;
  -webkit-mask: radial-gradient(circle 32cqmin at var(--uvq16-gx) var(--uvq16-gy),#000,rgba(0,0,0,.55) 45%,transparent);
  mask: radial-gradient(circle 32cqmin at var(--uvq16-gx) var(--uvq16-gy),#000,rgba(0,0,0,.55) 45%,transparent);
  animation: uvq16-sg-g calc(14s / var(--k)) ease-in-out infinite;
}

.pt-uvq16-seigaiha .gd .f {
  fill: color-mix(in srgb,var(--c1) 82%,var(--c3));
  stroke: var(--c3);
}

.pt-uvq16-seigaiha .gd .w {
  stroke: var(--c3);
}

.pt-uvq16-seigaiha .gd .w0 {
  fill: var(--c3);
}

.pt-uvq16-seigaiha[data-on] .gd {
  animation: none;
}

@keyframes uvq16-sg-dr {
  to {
    translate: calc(-80px / var(--d)) 0;
  }
}

@keyframes uvq16-sg-g {
  0%,100% {
    --uvq16-gx: 22%;
    --uvq16-gy: 30%;
  }
  33% {
    --uvq16-gx: 76%;
    --uvq16-gy: 24%;
  }
  66% {
    --uvq16-gx: 58%;
    --uvq16-gy: 78%;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-seigaiha .tl,.pt-uvq16-seigaiha .gd {
    animation: none;
  }
}

