  background: radial-gradient(90% 60% at 50% 105%,color-mix(in srgb,var(--c1) 22%,transparent),transparent 70%),radial-gradient(60% 50% at 8% 0%,color-mix(in srgb,var(--c2) 16%,transparent),transparent 70%),var(--bg);
}

.pt-uvq16-soap-bubbles i {
  position: absolute;
  left: var(--x);
  top: 100%;
  font-size: calc(var(--s) * var(--d) * .1);
  width: 10em;
  aspect-ratio: 1;
  margin-left: -5em;
  animation: uvq16-bb-up calc(var(--du) * 1s / var(--k)) linear infinite;
  animation-delay: calc(var(--dl) * 1s / var(--k));
  cursor: pointer;
}

.pt-uvq16-soap-bubbles b {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(circle at 70% 76%,rgba(255,255,255,.55) 0 4%,transparent 9%),radial-gradient(closest-side,transparent 82%,color-mix(in srgb,var(--fg) 14%,transparent) 97%,transparent);
  animation: uvq16-bb-sw calc(var(--sp) * 1s / var(--k)) ease-in-out infinite alternate;
}

.pt-uvq16-soap-bubbles b::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 0deg,var(--c1),var(--c2),var(--c3),var(--c1),var(--c2),var(--c3),var(--c1));
  -webkit-mask: radial-gradient(closest-side,transparent 60%,rgba(0,0,0,.35) 80%,#000 97%,transparent);
  mask: radial-gradient(closest-side,transparent 60%,rgba(0,0,0,.35) 80%,#000 97%,transparent);
  opacity: .8;
  animation: uvq16-bb-rot calc(7s / var(--k)) linear infinite;
}

.pt-uvq16-soap-bubbles b::after {
  content: "";
  position: absolute;
  left: 18%;
  top: 13%;
  width: 32%;
  height: 18%;
  border-radius: 50%;
  background: radial-gradient(closest-side,rgba(255,255,255,.95),rgba(255,255,255,0));
  rotate: -38deg;
}

.pt-uvq16-soap-bubbles i::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: .6em;
  height: .6em;
  margin: -.3em;
  border-radius: 50%;
  opacity: 0;
  pointer-events: none;
  box-shadow: 0 -6em var(--c1),4.2em -4.2em var(--c2),6em 0 var(--c3),4.2em 4.2em var(--c1),0 6em var(--c2),-4.2em 4.2em var(--c3),-6em 0 var(--c1),-4.2em -4.2em var(--c2);
}

.pt-uvq16-soap-bubbles i.pp b {
  animation: uvq16-bb-pop .3s ease-out forwards;
}

.pt-uvq16-soap-bubbles i.pp::after {
  animation: uvq16-bb-sp .45s ease-out forwards;
}

@keyframes uvq16-bb-up {
  from {
    transform: translateY(10%);
  }
  to {
    transform: translateY(calc(-100cqh - 120%));
  }
}

@keyframes uvq16-bb-sw {
  from {
    translate: -.8em 0;
    scale: 1 .97;
  }
  to {
    translate: .8em 0;
    scale: .97 1;
  }
}

@keyframes uvq16-bb-rot {
  to {
    rotate: 360deg;
  }
}

@keyframes uvq16-bb-pop {
  40% {
    scale: 1.15;
    opacity: .9;
  }
  100% {
    scale: 1.45;
    opacity: 0;
  }
}

@keyframes uvq16-bb-sp {
  0% {
    opacity: 1;
    scale: .4;
  }
  100% {
    opacity: 0;
    scale: 1.3;
  }
}

@media (prefers-reduced-motion:reduce) {
  .pt-uvq16-soap-bubbles i {
    animation-duration: calc(var(--du) * 3s);
  }
  .pt-uvq16-soap-bubbles b,.pt-uvq16-soap-bubbles b::before {
    animation: none;
  }
}

